import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { SavedReport } from '../types'
import {
  BOT_USER_AGENTS,
  BROWSER_USER_AGENT,
  audit,
  sitemapUrl,
  toMarkdown,
  type Check,
  type Fetched,
  type Status,
} from './audit'

type $ = EngineInterface

const PANE = 'aeo-audit'
const last = atom({ plugin: 'aeo-audit', key: 'last' } as const, null as SavedReport | null)
const running = atom({ plugin: 'aeo-audit', key: 'running' } as const, null as string | null)

const COLOR: Record<Status, string | undefined> = { pass: 'green', warn: 'yellow', fail: 'red', info: undefined }
const MARK: Record<Status, string> = { pass: 'PASS', warn: 'WARN', fail: 'FAIL', info: 'INFO' }

export function normalizeUrl(raw: string): string | undefined {
  const trimmed = raw.trim()
  if (trimmed === '') return undefined
  try {
    const url = new URL(/^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`)

    return url.hostname.includes('.') ? url.toString() : undefined
  } catch {
    return undefined
  }
}

// Follows redirects itself so the audit reads the page a crawler lands on.
async function get($: $, url: string, userAgent = BROWSER_USER_AGENT): Promise<Fetched | undefined> {
  let current = url
  try {
    for (let hop = 0; hop < 5; hop += 1) {
      const res = await $.http.fetch(current, { headers: { 'user-agent': userAgent, accept: 'text/html,*/*' } })
      const location = res.headers.location
      if (res.status >= 300 && res.status < 400 && location !== undefined) {
        current = new URL(location, current).toString()
        continue
      }

      return { status: res.status, headers: res.headers, text: res.text }
    }
  } catch {
    return undefined
  }

  return undefined
}

async function runAudit($: $, url: string): Promise<SavedReport> {
  const origin = new URL(url).origin
  await update($, running, () => url)
  $.ui.status(`AEO: auditing ${new URL(url).hostname}...`)
  try {
    const robots = await get($, `${origin}/robots.txt`)
    const robotsText = robots?.status === 200 ? robots.text : undefined
    const probeNames = Object.keys(BOT_USER_AGENTS)
    const [page, llms, sitemap, ...probes] = await Promise.all([
      get($, url),
      get($, `${origin}/llms.txt`),
      get($, sitemapUrl(robotsText, origin)),
      ...probeNames.map(name => get($, url, BOT_USER_AGENTS[name])),
    ])
    const report = audit({
      url,
      page: page ?? { status: 0, headers: {}, text: '' },
      robots,
      llms,
      sitemap,
      botProbes: Object.fromEntries(probeNames.map((name, i) => [name, probes[i]])),
    })

    const at = new Date(await $.clock.now()).toISOString()
    const day = at.slice(0, 10)
    const home = await $.env.get('HOME')
    const file = `${new URL(url).hostname}-${day}.md`
    let path: string | null = null
    if (home !== undefined) {
      path = `${home}/output/aeo-audits/${file}`
      try {
        await $.fs.write(path, `${toMarkdown(report, day)}\n`)
      } catch {
        path = null
      }
    }

    const saved: SavedReport = { ...report, at, path }
    await update($, last, () => saved)
    await $.store.set('last', saved)
    $.ui.status(`AEO: ${new URL(url).hostname} ${report.score}/100${report.isPartial ? ' (partial)' : ''}`)

    return saved
  } finally {
    await update($, running, () => null)
  }
}

function summary(report: SavedReport): string {
  const top = report.checks.filter(c => c.status === 'fail').map(c => `- ${c.label}`)

  return [
    `${report.url}: ${report.score}/100${report.isPartial ? ' (partial, the page refused the audit)' : ''}.`,
    `${report.counts.fail} fail, ${report.counts.warn} warn, ${report.counts.pass} pass.`,
    ...(top.length > 0 ? ['Failing:', ...top] : []),
    report.path === null ? 'Report not saved.' : `Report: ${report.path}`,
  ].join('\n')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'aeo',
      description: 'Audit a URL for AI answer engines (ChatGPT, Perplexity, AI Overviews, Copilot, Claude)',
      argumentHint: '<url>',
    })
    await $.tool.register({
      name: 'audit_site',
      description:
        'Audits one URL for AI answer-engine readiness: robots.txt access for each AI search crawler, firewall behaviour toward AI user agents, noindex/nosnippet, text visible without JavaScript, title, description, canonical, H1, question-shaped sections, schema, sitemap, llms.txt. Returns a markdown report with sources and fixes, and saves it under ~/output/aeo-audits/.',
      inputSchema: {
        type: 'object',
        properties: { url: { type: 'string', description: 'The page to audit, e.g. https://example.com/pricing' } },
        required: ['url'],
      },
    })
    if ((await read($, last)) === null) {
      const stored = await $.store.get('last')
      if (stored !== undefined && stored !== null) await update($, last, () => stored as SavedReport)
    }

    return next(e)
  })

  on('command.run', { command: 'aeo' }, async ($, e) => {
    if (e.args.trim() === '') {
      const opened = await $.ui.open({ id: PANE, title: 'AEO audit' })

      return { text: (await read($, last)) === null ? 'Usage: /aeo <url>' : opened.isPlaced ? 'AEO pane opened.' : `AEO pane waiting: ${opened.reason}` }
    }
    const url = normalizeUrl(e.args)
    if (url === undefined) return { text: `Not a URL: ${e.args.trim()}` }
    void $.ui.open({ id: PANE, title: 'AEO audit' })
    const report = await runAudit($, url)

    return { text: summary(report) }
  })

  on('tool.call', { tool: 'mcp__aeo-audit__audit_site' }, async ($, e) => {
    // A plugin tool's arguments arrive on the event itself, beside `tool` and `tool_use_id`.
    const url = normalizeUrl(String((e as { url?: unknown }).url ?? ''))
    if (url === undefined) return { deny: 'audit_site needs a full URL such as https://example.com/' }
    const report = await runAudit($, url)

    return { result: `${toMarkdown(report, report.at.slice(0, 10))}\n\n${report.path === null ? '' : `Saved: ${report.path}`}` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const report = await read($, last)
    const busy = await read($, running)

    if (report === null) {
      return (
        <Box flexDirection="column">
          <Text>{busy === null ? 'No audit yet. Run /aeo <url>.' : `Auditing ${busy}...`}</Text>
        </Box>
      )
    }

    const scoreColor = report.score >= 80 ? 'green' : report.score >= 50 ? 'yellow' : 'red'
    const row = (c: Check) => (
      <Box key={c.id} flexDirection="column">
        <Text wrap="truncate-end">
          <Text color={COLOR[c.status]} bold={c.status === 'fail'}>
            {MARK[c.status]}
          </Text>{' '}
          {c.label}
        </Text>
        {(c.status === 'fail' || c.status === 'warn') && (
          <Text dimColor wrap="wrap">
            {'     '}
            {c.fix ?? c.detail}
          </Text>
        )}
      </Box>
    )

    return (
      <Box flexDirection="column">
        <Text bold wrap="truncate-end">
          {report.url}
        </Text>
        <Text>
          <Text color={scoreColor} bold>
            {report.score}/100
          </Text>
          <Text dimColor>
            {'  '}
            {report.counts.fail} fail, {report.counts.warn} warn, {report.counts.pass} pass
            {report.isPartial ? ', partial' : ''}
          </Text>
        </Text>
        {busy !== null && <Text color="yellow">Re-auditing {busy}...</Text>}
        {(['Crawler access', 'Page', 'Content', 'Extras'] as const).map(group => {
          const rows = report.checks.filter(c => c.group === group)
          if (rows.length === 0) return null

          return (
            <Box key={group} flexDirection="column" marginTop={1}>
              <Text bold>{group}</Text>
              {rows.map(row)}
            </Box>
          )
        })}
        <Box marginTop={1}>
          <Button
            key="fix"
            label="Fix with Claude"
            hotkey="f"
            variant="primary"
            onPress={async () => {
              const live = await read($, last)
              if (live === null) return
              const where = live.path === null ? 'the AEO audit in this session' : `the AEO audit at ${live.path}`
              await $.prompt.fill({
                text: `Read ${where} for ${live.url} and write the exact fixes for every FAIL and WARN, most impact first. Quote the source for each.`,
              })
            }}
          />
          <Text> </Text>
          <Button
            key="rerun"
            label="Rerun"
            hotkey="r"
            onPress={async () => {
              const live = await read($, last)
              if (live !== null) await runAudit($, live.url)
            }}
          />
        </Box>
      </Box>
    )
  })
}

