// Self-contained: the analyzer and the hooks module import these from here.
export type Status = 'pass' | 'warn' | 'fail' | 'info'

export type Check = {
  id: string
  group: 'Crawler access' | 'Page' | 'Content' | 'Extras'
  label: string
  status: Status
  detail: string
  fix?: string
  source?: string
  // How much this check counts toward the score; 0 for info-only checks.
  weight: number
}

export type Report = {
  url: string
  score: number
  // True when the page itself could not be read, so content checks were skipped.
  isPartial: boolean
  counts: Record<Status, number>
  checks: Check[]
}

export type SavedReport = Report & { at: string; path: string | null }

declare module 'claude-code' {
  interface PluginState {
    'aeo-audit': {
      last: SavedReport | null
      running: string | null
    }
  }
}
